#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<bool> isPrime(n + 1, true);
    isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (long long i = 2; i * i <= n; i++)
        if (isPrime[i])
            for (long long j = i * i; j <= n; j += i) isPrime[j] = false;
    int count = 0;
    for (int i = 0; i <= n; i++) if (isPrime[i]) count++;
    cout << count << endl;
    return 0;
}

